  "packet_id": "H6-T01-2",
  "claim_id": "C058",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C058.component",
    "value": "Trial monitoring must track late-start frequency and minutes together with completed bookings, workload, safety and displaced demand.",
    "scope": "Joint outcome-monitoring requirement; no weighting or tradeoff rule among these measures is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P030 explicitly supplies the joint monitoring requirement and all listed measures."
    }
  },
  "signal_basis": {
    "component_id": "C058.signal_basis",
    "value": "A reduced configuration repeatedly reproduces lateness while specified further removals do not. This provides test-relative evidence, while field effectiveness remains unestablished; the proposed trial must respect staffing, equipment, safety and service constraints and cannot count deadline or availability relabelling alone as improvement.",
    "scope": "Evidence for the selected replay and the limits governing subsequent field-trial evaluation.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
